1	package main
2	
3	import (
4		"errors"
5		"testing"
6	)
7	
8	func TestConvert(t *testing.T) {
9		t.Parallel()
10	
11		sizes := map[string]PackSizes{"BOLT-M6": {PiecesPerBox: 50, BoxesPerPallet: 40}}
12	
13		cases := []struct {
14			name     string
15			qty      int
16			from, to string
17			want     int
18		}{
19			{"pcs to boxes", 150, "pcs", "boxes", 3},
20			{"boxes to pallets", 80, "boxes", "pallets", 2},
21			{"pallets to pcs", 1, "pallets", "pcs", 2000},
22		}
23		for _, tc := range cases {
24			t.Run(tc.name, func(t *testing.T) {
25				t.Parallel()
26				got, err := Convert("BOLT-M6", sizes, tc.qty, tc.from, tc.to)
27				if err != nil || got != tc.want {
28					t.Fatalf("Convert = %d, %v; want %d", got, err, tc.want)
29				}
30			})
31		}
32	
33		t.Run("missing pack size refused", func(t *testing.T) {
34			t.Parallel()
35			if _, err := Convert("NUT-M8", sizes, 1, "boxes", "pcs"); !errors.Is(err, ErrNoPackSize) {
36				t.Fatalf("want ErrNoPackSize, got %v", err)
37			}
38		})
39	
40		t.Run("non whole result refused", func(t *testing.T) {
41			t.Parallel()
42			if _, err := Convert("BOLT-M6", sizes, 7, "pcs", "boxes"); err == nil {
43				t.Fatal("want an error for 7 pcs in boxes of 50")
44			}
45		})
46	}
